<?php declare(strict_types=1); require __DIR__.'/_bootstrap.php'; require_admin(); $id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT)?:0;$row=['media_type'=>'photo','title'=>'','description'=>'','media_path'=>'','thumbnail_path'=>'','product_id'=>null,'is_active'=>1,'sort_order'=>0];if($id){$q=$pdo->prepare('SELECT * FROM gallery_media WHERE id=?');$q->execute([$id]);$row=$q->fetch()?:$row;}$error='';
function upload_media_file(string $field,string $type):?string{global $config;if(empty($_FILES[$field])||$_FILES[$field]['error']===UPLOAD_ERR_NO_FILE)return null;if($_FILES[$field]['error']!==UPLOAD_ERR_OK)throw new RuntimeException('Upload failed.');if($_FILES[$field]['size']>($config['app']['upload_max_bytes']??5242880))throw new RuntimeException('File exceeds upload limit.');$tmp=$_FILES[$field]['tmp_name'];$f=new finfo(FILEINFO_MIME_TYPE);$mime=$f->file($tmp);$allowed=$type==='photo'?['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp']:['video/mp4'=>'mp4','video/webm'=>'webm','video/ogg'=>'ogv'];if(!isset($allowed[$mime]))throw new RuntimeException('Unsupported file format.');$name=bin2hex(random_bytes(18)).'.'.$allowed[$mime];$rel='assets/uploads/media/'.$name;$dest=dirname(__DIR__).'/'.$rel;if(!is_dir(dirname($dest)))mkdir(dirname($dest),0755,true);if(!move_uploaded_file($tmp,$dest))throw new RuntimeException('Could not save upload.');return $rel;}
if(is_post()){verify_csrf($_POST['csrf']??'');$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT)?:0;$type=($_POST['media_type']??'photo')==='video'?'video':'photo';$title=trim((string)($_POST['title']??''));$desc=trim((string)($_POST['description']??''));$pid=filter_input(INPUT_POST,'product_id',FILTER_VALIDATE_INT)?:null;$active=isset($_POST['is_active'])?1:0;$sort=(int)($_POST['sort_order']??0);if($title==='')$error='Title is required.';else{try{$old=$id?(function()use($pdo,$id){$q=$pdo->prepare('SELECT * FROM gallery_media WHERE id=?');$q->execute([$id]);return $q->fetch();})():null;$media=upload_media_file('media',$type)??($old['media_path']??null);if(!$media)$error='Please upload a media file.';else{$thumb=upload_media_file('thumbnail','photo')??($old['thumbnail_path']??null);if($id){$q=$pdo->prepare('UPDATE gallery_media SET media_type=?,title=?,description=?,media_path=?,thumbnail_path=?,product_id=?,is_active=?,sort_order=? WHERE id=?');$q->execute([$type,$title,$desc?:null,$media,$thumb,$pid,$active,$sort,$id]);}else{$q=$pdo->prepare('INSERT INTO gallery_media(media_type,title,description,media_path,thumbnail_path,product_id,is_active,sort_order) VALUES(?,?,?,?,?,?,?,?)');$q->execute([$type,$title,$desc?:null,$media,$thumb,$pid,$active,$sort]);}flash('success','Gallery media saved.');redirect_to('media.php');}}catch(Throwable $ex){$error=$ex->getMessage();}}}
$products=$pdo->query('SELECT id,name FROM products ORDER BY sort_order,id')->fetchAll();$pageTitle=$id?'Edit Media':'Upload Media';$active='media';require __DIR__.'/includes/layout.php';if($error):?><div class="flash error"><?=e($error)?></div><?php endif;?><div class="panel form-card"><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="id" value="<?=(int)$id?>"><div class="grid2"><div class="field"><label>Media type</label><select name="media_type" id="mediaType"><option value="photo" <?=$row['media_type']==='photo'?'selected':''?>>Photo</option><option value="video" <?=$row['media_type']==='video'?'selected':''?>>Video</option></select></div><div class="field"><label>Related fabric</label><select name="product_id"><option value="">General store media</option><?php foreach($products as $p):?><option value="<?=$p['id']?>" <?=$row['product_id']==$p['id']?'selected':''?>><?=e($p['name'])?></option><?php endforeach;?></select></div></div><div class="field"><label>Title *</label><input name="title" value="<?=e($row['title'])?>" required></div><div class="field"><label>Description</label><textarea name="description" rows="3"><?=e($row['description'])?></textarea></div><div class="grid2"><div class="field"><label>Media file *</label><input name="media" type="file" accept="image/jpeg,image/png,image/webp,video/mp4,video/webm,video/ogg"></div><div class="field"><label>Video thumbnail (optional)</label><input name="thumbnail" type="file" accept="image/jpeg,image/png,image/webp"></div></div><div class="grid2"><div class="field"><label>Display order</label><input name="sort_order" type="number" value="<?=e((string)$row['sort_order'])?>"></div><div class="field"><label><input type="checkbox" name="is_active" <?=$row['is_active']?'checked':''?>> Publish</label></div></div><button class="btn btn-gold">Save Media</button> <a class="btn btn-light" href="media.php">Cancel</a></form></div><?php require __DIR__.'/includes/footer.php';?>
